// Code by Flopine

// Thanks to wsmind, leon, XT95, lsdlive, lamogui, 
// Coyhot, Alkama,YX, NuSan, slerpy, wwrighter 
// BigWings, FabriceNeyret and Blackle for teaching me

// Thanks LJ for giving me the spark :3

// Thanks to the Cookie Collective, which build a cozy and safe environment for me 
// and other to sprout :)  
// https://twitter.com/CookieDemoparty

// Genuary #05 : Isometric Art
//Press Up key to restart the simulation


#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define PI acos(-1.)

float box (vec3 p, vec3 c)
{
    vec3 q = abs(p)-c;
    return min(0., max(q.x,max(q.y, q.z)))+length(max(q, 0.));
}

vec2 SDF (vec3 p)
{
    p.yz *= rot(-atan(1./sqrt(2.)));
    p.xz *= rot(PI/4.0);
    p.z += iTime;

    vec2 id = floor(p.xz)+.5;
    float state = texture(iChannel0, id/iResolution.xy*1.5).x;
    vec3 center = vec3(id.x, 0., id.y);
    float size = mix(.1, .35, ceil(state));

    return vec2(box(p-center, vec3(size)), state);
}

vec3 gn (vec3 p)
{
    vec2 eps = vec2(0.01, 0.);
    return normalize(SDF(p).x-vec3(SDF(p-eps.xyy).x,SDF(p-eps.yxy).x, SDF(p-eps.yyx).x));
}

float AO (vec3 p, vec3 n, float e)
{return clamp(SDF(p+e*n).x/e, 0., 1.);}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;
    vec3 ro=vec3(uv*12., -20.), rd=vec3(0.,0.,1.), p=ro,
    col=vec3(0.);

    bool hit = false; 
    vec2 sd;
    for (float i=0.; i<40.; i++)
    {
        sd = SDF(p);
        if (sd.x < 0.01)
        {
            hit = true; break;
        }
        p += sd.x*rd*.5;
    }

    if (hit)
    {
        vec3 n = gn(p);
        float ao = AO(p, n, 0.15) + AO(p, n, 0.2) + AO(p, n, 0.25);
        col = mix(vec3(0.02), vec3(0.8, .95, 1.), sd.y);
        col *= ao/3.;
    }

    fragColor = vec4(sqrt(col),1.0);
}

#define tex(u) texelFetch(iChannel0, u, 0).x

#define key texelFetch(iChannel2, ivec2(38, 0),0).x
#define iFrame ((key>.5) ? 0 : iFrame)

float kernel_sum (ivec2 pixel)
{
    float sum = 0.;

    sum += tex(pixel+ivec2(0., -1.));
    sum += tex(pixel+ivec2(1., -1.));
    sum += tex(pixel+ivec2(1., 0.));
    sum += tex(pixel+ivec2(1., 1.));
    sum += tex(pixel+ivec2(0., 1.));
    sum += tex(pixel+ivec2(-1., 1.));
    sum += tex(pixel+ivec2(-1., 0.));
    sum += tex(pixel+ivec2(-1., -1.));

    return sum;
}

void isAlive (inout float cell, float sum)
{
    if(cell > .5)
    {
        if (sum < 2. || sum > 3.) 
        {
            cell = 0.;
            return;
        } 
    }
    if (sum == 3.)
    {
        cell = 1.;
        return;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy/iResolution.xy;
    ivec2 pixel = ivec2(int(fragCoord.x),int(fragCoord.y));
    if (iFrame == 0)
    {
        fragColor = vec4(step(.5,texture(iChannel1, uv)));
        return;
    }

    float cell_state = texture(iChannel0, uv).x; 
    if (iFrame%int(iFrameRate*.1) == 0)
    {
        isAlive(cell_state, kernel_sum(pixel));    
    }    
    fragColor = vec4(cell_state);
}
